from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class ImpactedCellInfo(SchemaObject):
    nr_cell_identity = SchemaField(name='nrCellIdentity')
    nr_cell_id = SchemaField(name='nrCellId')

    def __init__(self, nr_cell_identity, nr_cell_id):
        self.nr_cell_identity = nr_cell_identity
        self.nr_cell_id = nr_cell_id

        super(ImpactedCellInfo, self).__init__()


class ImpactedCells(SchemaObject):
    impact_on_cells = SchemaField(name='impactOnCells', many=True, klass=ImpactedCellInfo)
    impact_scope = SchemaField(name='impactScope')

    def __init__(self, impact_on_cells, impact_scope):
        self.impact_on_cells = impact_on_cells
        self.impact_scope = impact_scope

        super(ImpactedCells, self).__init__()


class FaultSignature(SchemaObject):
    date = SchemaField(name='date', optional=True)
    reset_counter = SchemaField(name='resetCounter', optional=True)
    category = SchemaField(name='category', optional=True)
    scope = SchemaField(name='scope', optional=True)
    load_name = SchemaField(name='loadName', optional=True)
    component = SchemaField(name='component', optional=True)
    minor = SchemaField(name='minor', optional=True)
    rfm_gpp = SchemaField(name='rfmGpp', optional=True)
    rfm_cpri = SchemaField(name='rfmCpri', optional=True)
    rfm_fpga = SchemaField(name='rfmFpga', optional=True)
    info = SchemaField(name='info', optional=True)
    extra_info = SchemaField(name='extraInfo', optional=True)

    def __init__(self, date, reset_counter, category, scope, load_name, component, minor, rfm_gpp, rfm_cpri, rfm_fpga,
                 info, extra_info):
        self.date = date
        self.reset_counter = reset_counter
        self.category = category
        self.scope = scope
        self.load_name = load_name
        self.component = component
        self.minor = minor
        self.rfm_gpp = rfm_gpp
        self.rfm_cpri = rfm_cpri
        self.rfm_fpga = rfm_fpga
        self.info = info
        self.extra_info = extra_info

        super(FaultSignature, self).__init__()


class HistoricalAlarmsV2(SchemaObject):
    uuid = SchemaField(name="uuid", not_null=True)
    severity = SchemaField(name="severity", not_null=True)
    alarm_id = SchemaField(name="alarmId")
    alarm_name = SchemaField(name="alarmName")
    fault_id = SchemaField(name="faultId", not_null=True)
    fault_name = SchemaField(name="faultName", not_null=True)
    alarming_object = SchemaField(name="alarmingObject", optional=True)
    appear_time = SchemaField(name="appearTime", not_null=True)
    last_updated_time = SchemaField(name="lastUpdatedTime", optional=True)
    probable_cause_name = SchemaField(name="probableCauseName")
    additional_info = SchemaField(name="additionalInfo", not_null=True)
    event_type_name = SchemaField(name="eventTypeName", not_null=True)
    cleared_time = SchemaField(name="clearedTime", not_null=True)
    fault_signature = SchemaField(name='faultSignature', klass=FaultSignature, optional=True)
    faulty_cells = SchemaField(name='faultyCells', klass=ImpactedCells, not_null=True)
    degraded_cells = SchemaField(name='degradedCells', klass=ImpactedCells, not_null=True)
    affected_cells = SchemaField(name='affectedCells', klass=ImpactedCells, not_null=True)

    def __init__(self, uuid, severity, alarm_id, alarm_name, fault_id, fault_name, alarming_object, appear_time,
                 last_updated_time, probable_cause_name, additional_info, event_type_name, cleared_time,
                 fault_signature, faulty_cells, degraded_cells, affected_cells):
        self.uuid = uuid
        self.severity = severity
        self.alarm_id = alarm_id
        self.alarm_name = alarm_name
        self.fault_id = fault_id
        self.fault_name = fault_name
        self.alarming_object = alarming_object
        self.appear_time = appear_time
        self.last_updated_time = last_updated_time
        self.probable_cause_name = probable_cause_name
        self.additional_info = additional_info
        self.event_type_name = event_type_name
        self.cleared_time = cleared_time
        self.fault_signature = fault_signature
        self.faulty_cells = faulty_cells
        self.degraded_cells = degraded_cells
        self.affected_cells = affected_cells

        super(HistoricalAlarmsV2, self).__init__()


class HistoricalAlarmsLicensedV2(SchemaObject):
    total = SchemaField(name="total")
    alarms = SchemaField(name="alarms", klass=HistoricalAlarmsV2, many=True)

    def __init__(self, total, alarms):
        self.total = total
        self.alarms = alarms

        super(HistoricalAlarmsLicensedV2, self).__init__()
